{
  "name": "irene test - include (A OR B) & (C OR D)",
  "description": "retarget users that fall in any of the following group combos: AC, BC, AD, BD; A = served 2+ impressions from specified advertiser within last 8 hours, B = clicked specified package's ads at least once within last 20 hours, C = caused 2+ pixel fires in last 8 hours, D = pixel fires increased by 50% in 2 days",
  "ruleSet": {
    "op": "and",
    "ruleSets": [
        {
            "op": "or",
            "rules": [
                {
                    "invertRule": false,
                    "event": "advertiserImpression",
                    "eventObjectResourceIds": ["{{advertiserId}}"],
                    "frequency": {
                    "minimum": 2,
                    "period": 8,
                    "periodUnits": "hours"
                    }
                },
                {
                    "invertRule": false,
                    "event": "packageClick",
                    "eventObjectResourceIds": ["{{packageId}}"],
                    "frequency": {
                    "minimum": 1,
                    "period": 20,
                    "periodUnits": "hours"
                    }
                }
            ]
        },
        {
            "op": "or",
            "rules": [
                {
                    "invertRule": false,
                    "event": "beaconImpression",
                    "eventObjectResourceIds": ["{{beaconId}}"],
                    "frequency": {
                        "minimum": 2,
                        "period": 8,
                        "periodUnits": "hours"
                    }
                },
                {
                    "invertRule": false,
                    "event": "beaconImpression",
                    "eventObjectResourceIds": ["{{beaconId}}"],
                    "velocity": {
                        "periodInDays": 2,
                        "change": 50
                    }
                }
            ]
        }
    ]
  }
}

